create or replace function public.radio_now() returns table(schedule_id uuid, track_id uuid, title text, object_path text, starts_at timestamptz, ends_at timestamptz, server_now timestamptz) language sql stable security invoker set search_path = '' as $$ select s.id,t.id,t.title,t.object_path,s.starts_at,s.ends_at,statement_timestamp() from public.radio_schedule s join public.tracks t on t.id=s.track_id where t.published and t.rights_confirmed and s.starts_at <= statement_timestamp() and s.ends_at > statement_timestamp() order by s.starts_at desc limit 1 $$; revoke all on function public.radio_now() from public; grant execute on function public.radio_now() to anon, authenticated;
